const lessons=await fetch('./lessons.json').then(r=>r.json());
const $=s=>document.querySelector(s);let state={done:[],notes:{},drafts:{},quiz:{},current:0};try{const s=JSON.parse(localStorage.getItem('arraystep-v1'));if(s&&Array.isArray(s.done))state={...state,...s}}catch{}
let current=Math.max(0,Math.min(lessons.length-1,Number(state.current)||0)),tab='learn';const esc=s=>String(s).replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
function save(){state.current=current;try{localStorage.setItem('arraystep-v1',JSON.stringify(state))}catch{$('#saved')?.replaceChildren('Browser storage unavailable. Export your progress.')}}
function nav(){let q=$('#search').value.toLowerCase();$('#roadmap').innerHTML=lessons.map((l,i)=>l.category===category && (l.title+' '+l.problem).toLowerCase().includes(q)?`<button class="${i===current?'active':''}" data-i="${i}" ${i===current?'aria-current="step"':''}><span>${state.done.includes(i)?'✓':String(pathIds().indexOf(i)+1).padStart(2,'0')}</span>${esc(l.title)}</button>`:'').join('');document.querySelectorAll('[data-i]').forEach(b=>b.onclick=()=>{current=+b.dataset.i;tab='learn';render();save()});$('#count').textContent=`${pathIds().filter(i=>state.done.includes(i)).length} of ${pathIds().length} topics completed`;$('#progress').max=pathIds().length;$('#progress').value=pathIds().filter(i=>state.done.includes(i)).length}
function render(){nav();let l=lessons[current];$('#title').textContent=l.title;$('#level').textContent=l.level+' / '+paths[category].name.toUpperCase();$('#position').textContent=`TOPIC ${pathIds().indexOf(current)+1} / ${pathIds().length}`;document.querySelectorAll('[data-tab]').forEach(b=>b.classList.toggle('active',b.dataset.tab===tab));$('#prev').disabled=pathIds().indexOf(current)===0;$('#next').disabled=pathIds().indexOf(current)===pathIds().length-1;document.querySelector('.toolbar span:last-child').textContent=paths[category].name+' · '+pathIds().length+' units';
if(tab==='learn'){$('#panel').innerHTML=`<p>${esc(l.lesson)}</p><h3>Read & trace</h3><pre><code>${esc(l.code)}</code></pre><span class="pill">${esc(l.complexity)}</span><div class="callout">Before you code: explain the invariant in your own words. Trace the example on paper, then test a small edge case.</div><button class="primary" id="go">Try the practice →</button>`;$('#go').onclick=()=>{tab='practice';render()}}
if(tab==='practice'){$('#panel').innerHTML=`<div class="eyebrow">PATTERN PRACTICE</div><h3>${esc(l.problem)}</h3>${l.task ? `<div class="callout">${esc(l.task)}</div>` : `<p>Read the problem constraints, explain your approach, then implement and test it.</p><p><a target="_blank" rel="noopener noreferrer" href="https://leetcode.com/problems/${l.slug}/">Open problem on LeetCode ↗</a></p>`}<label>Your answer / Python scratchpad<textarea id="draft" spellcheck="false" placeholder="# Write your approach and Python here…"></textarea></label><p id="saved">Saved on this device. This editor does not execute Python; run code in your Python environment or on the linked problem.</p><details><summary>Show a thinking hint</summary><p>${esc(l.lesson)} Aim for ${esc(l.complexity)} where applicable.</p></details><p><button class="primary" id="recall">Check your understanding →</button></p>`;$('#draft').value=state.drafts[current]||'';$('#draft').oninput=e=>{state.drafts[current]=e.target.value;save()};$('#recall').onclick=()=>{tab='review';render()}}
if(tab==='review'){$('#panel').innerHTML=`<h3>${esc(l.question)}</h3><div class="options">${l.options.map((o,i)=>`<button data-answer="${i}">${String.fromCharCode(65+i)}. ${esc(o)}</button>`).join('')}</div><div id="feedback" role="status"></div><label>My takeaway & mistakes<textarea id="note" placeholder="What pattern did you learn? What would you test next time?"></textarea></label><p id="saved">Notes save automatically on this device.</p><button id="complete" class="primary">${state.done.includes(current)?'Completed ✓ · Mark for review':'Mark topic complete ✓'}</button>`;$('#note').value=state.notes[current]||'';$('#note').oninput=e=>{state.notes[current]=e.target.value;save()};document.querySelectorAll('[data-answer]').forEach(b=>b.onclick=()=>{let ok=+b.dataset.answer===l.answer;$('#feedback').textContent=ok?'Correct. '+l.lesson:'Try again. Review the invariant in the lesson.';state.quiz[current]=state.quiz[current]||ok;save()});$('#complete').onclick=()=>{if(state.done.includes(current))state.done=state.done.filter(i=>i!==current);else state.done.push(current);save();render()}}
}

const paths={
 python:{name:'Python foundations',icon:'Py',desc:'Build fluency with types, loops, functions and reliable code.',color:'mint'},
 algorithms:{name:'Arrays & algorithms',icon:'[ ]',desc:'Find the pattern: pointers, windows, prefix sums and search.',color:'sage'},
 structures:{name:'Data structures',icon:'{ }',desc:'Strings, stacks, trees, graphs and heaps. Choose the right tool.',color:'blue'},
 math:{name:'Math for problem solving',icon:'∑',desc:'Numbers, probability, vectors and optimization, one idea at a time.',color:'sand'},
 ml:{name:'Machine learning',icon:'ML',desc:'Train, evaluate and improve models with sound experiments.',color:'purple'},
 ai:{name:'AI engineering',icon:'✦',desc:'Embeddings, retrieval, generative systems and thoughtful evaluation.',color:'pink'},
 software:{name:'Software engineering',icon:'</>',desc:'Testing, Git, SQL, APIs and systems that handle failure.',color:'blue'},
 interview:{name:'Interview & exam practice',icon:'↗',desc:'Explain clearly, practice under time pressure and learn from mistakes.',color:'sand'}
};
let category='python';
const hub=document.createElement('section');hub.id='hub';document.querySelector('header').after(hub);
function pathIds(){return lessons.flatMap((l,i)=>l.category===category?[i]:[])}
function openLesson(i){current=i;category=lessons[i].category;tab='learn';hub.hidden=true;document.querySelector('.layout').hidden=false;render();save();window.scrollTo(0,0)}
function showHome(){document.querySelector('.layout').hidden=true;hub.hidden=false;let done=state.done.length;let xp=done*50+Object.values(state.quiz).filter(Boolean).length*10;
 hub.innerHTML=`<div class="hub-intro"><div><div class="eyebrow">YOUR PERSONAL LEARNING CAMPUS</div><h1>Build skills.<br><em>Unlock your next chapter.</em></h1><p>From your first Python function to ML and software interviews.<br>Choose a path. Learn a concept. Put it into practice.</p></div><div class="score"><b>${xp}</b><span>XP EARNED</span><strong>${done} / ${lessons.length} completed</strong><small>${done>=30?'Pattern explorer':done>=10?'Skill builder':'Curious beginner'} · ${Math.floor(done/10)} milestones earned</small></div></div><div class="daily"><div><div class="eyebrow">TODAY’S CHALLENGE</div><h3>${esc(lessons[dailyIndex()].problem)}</h3><p>A small step counts. Try one problem, then write what you learned.</p></div><button class="primary" id="daily-start">Take the challenge →</button></div><div class="section-title"><h2>Choose your learning path</h2><span>${lessons.length} bite-size units · 8 paths</span></div><div class="path-grid">${Object.entries(paths).map(([key,p])=>{let ids=lessons.flatMap((l,i)=>l.category===key?[i]:[]),n=ids.filter(i=>state.done.includes(i)).length;return `<button class="path-card ${p.color}" data-path="${key}"><span class="path-icon">${esc(p.icon)}</span><span class="path-meta">${ids.length} UNITS · GUIDED PRACTICE</span><h3>${p.name}</h3><p>${p.desc}</p><progress max="${ids.length}" value="${n}"></progress><div>${n} completed <strong>Explore path →</strong></div></button>`}).join('')}</div><p class="disclaimer">A growing study collection, not an exhaustive syllabus or a guarantee of exam or interview results. Match your preparation to your course or role.</p>`;
 document.querySelectorAll('[data-path]').forEach(b=>b.onclick=()=>showList(b.dataset.path));$('#daily-start').onclick=()=>openLesson(dailyIndex());window.scrollTo(0,0)}
function dailyIndex(){let date=new Date();let day=Math.floor(Date.UTC(date.getFullYear(),date.getMonth(),date.getDate())/86400000);return day%lessons.length}
function showList(key){category=key;document.querySelector('.layout').hidden=true;hub.hidden=false;let p=paths[key];let ids=pathIds();hub.innerHTML=`<button id="back-campus">← All learning paths</button><div class="list-intro"><div class="eyebrow">${p.name.toUpperCase()} / YOUR ROADMAP</div><h1>${p.name}</h1><p>${p.desc}</p><div class="callout">Suggested routine: learn for 5 minutes, attempt the task for 10–20 minutes, then answer the recall quiz. Earn 50 XP per completed unit and 10 XP per correct quiz.</div></div><label>Search this path<input id="list-search" placeholder="Search topics or problems…"></label><div id="problem-list"></div>`;function list(){let q=$('#list-search').value.toLowerCase();let matches=ids.filter(i=>(lessons[i].title+' '+lessons[i].problem).toLowerCase().includes(q));$('#problem-list').innerHTML=matches.length?matches.map((i)=>{let l=lessons[i];return `<button class="problem-row" data-open="${i}"><span class="problem-num">${state.done.includes(i)?'✓':String(ids.indexOf(i)+1).padStart(2,'0')}</span><span><b>${esc(l.title)}</b><small>${esc(l.problem)}</small></span><span class="pill">${l.level}</span><span>→</span></button>`}).join(''):'<p>No matching topics. Try a different search.</p>';document.querySelectorAll('[data-open]').forEach(b=>b.onclick=()=>openLesson(+b.dataset.open))}$('#list-search').oninput=list;$('#back-campus').onclick=showHome;list();window.scrollTo(0,0)}
document.querySelector('.brand').onclick=e=>{e.preventDefault();showHome()};
const back=document.createElement('button');back.id='back-list';back.textContent='← Back to problem list';document.querySelector('main').prepend(back);back.onclick=()=>showList(category);

document.querySelectorAll('[data-tab]').forEach(b=>b.onclick=()=>{tab=b.dataset.tab;render()});$('#search').oninput=nav;$('#prev').onclick=()=>{current=pathIds()[pathIds().indexOf(current)-1];tab='learn';save();render()};$('#next').onclick=()=>{current=pathIds()[pathIds().indexOf(current)+1];tab='learn';save();render()};$('#about').onclick=()=>$('#about-dialog').showModal();$('#install').onclick=()=>$('#guide').showModal();$('#export').onclick=async()=>{if(window.arraystepNative?.active){try{await window.arraystepNative.exportProgress(state)}catch{alert('Backup sharing was cancelled or unavailable. Your progress is still on this device.')}return}let a=document.createElement('a');a.href=URL.createObjectURL(new Blob([JSON.stringify(state,null,2)],{type:'application/json'}));a.download='arraystep-progress.json';a.click();setTimeout(()=>URL.revokeObjectURL(a.href),1000)};$('#import').onchange=async e=>{try{let s=JSON.parse(await e.target.files[0].text());if(!Array.isArray(s.done)||s.done.some(i=>!Number.isInteger(i)||i<0||i>=lessons.length))throw Error();for(let k of ['notes','drafts','quiz'])if(!s[k]||typeof s[k]!=='object'||Array.isArray(s[k]))throw Error();if(!confirm('Replace this browser’s progress with the imported backup?'))return;state={...state,...s,done:[...new Set(s.done)]};current=Math.max(0,Math.min(lessons.length-1,Number(s.current)||0));category=lessons[current].category;save();showHome()}catch{alert('Could not read this backup. Please choose an ArrayStep progress export.')}};showHome();
document.addEventListener('click',async e=>{const a=e.target.closest('a[href]');if(window.arraystepNative?.active&&a&&a.href.startsWith('https://leetcode.com/')){e.preventDefault();try{await window.arraystepNative.open(a.href)}catch{alert('Could not open the external problem. Please try again.')}}});
if(!window.arraystepNative?.active&&'serviceWorker'in navigator)navigator.serviceWorker.register('./sw.js').catch(()=>{});
